    lawNameSi: "\u0daf\u0dab\u0dca\u0da9 \u0db1\u0dd3\u0dad\u0dd2 \u0dc3\u0d82\u0d9c\u0dca\u200d\u0dbb\u0dc4\u0dba\u0dda 312 \u0dc0\u0d9c\u0db1\u0dca\u0dad\u0dd2\u0dba",
