    recommendedAction: "Report physical assault to police.",
    recommendedActionSi: "\u0dc1\u0dcf\u0dbb\u0dd3\u0dbb\u0dd2\u0d9a \u0db4\u0dc4\u0dbb\u0daf\u0dd3\u0db8\u0dca \u0db4\u0dd2\u0dc5\u0dd2\u0db6\u0db3\u0dc0 \u0db4\u0ddc\u0dbd\u0dd2\u0dc3\u0dd2\u0dba\u0da7 \u0dc0\u0dcf\u0dbb\u0dca\u0dad\u0dcf \u0d9a\u0dbb\u0db1\u0dca\u0db1."
