    section: "345",
    category: "sexual_harassment",
    keywords: ["sexual harassment", "inappropriate touch", "modesty", "harassment"],
    whyRelevant: "Prohibits sexually harassing a person by assault, criminal force, words, or gestures causing sexual annoyance or distress.",
